const reduced=matchMedia('(prefers-reduced-motion: reduce)');
if(!reduced.matches&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.memories h2,.gallery-intro,.photo-grid,.letter,.moment,.ending h2').forEach(el=>{el.classList.add('reveal');observer.observe(el)});const hero=document.querySelector('.hero');for(let i=0;i<18;i++){const star=document.createElement('span');star.className='sparkle';star.setAttribute('aria-hidden','true');star.style.cssText=`left:${8+Math.random()*84}%;top:${10+Math.random()*75}%;animation-delay:${Math.random()*5}s`;hero.append(star)}}
const progress=document.createElement('div');progress.className='reading-progress';progress.setAttribute('aria-hidden','true');document.body.append(progress);let pending=false;function updateProgress(){const total=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${total>0?scrollY/total:0})`;pending=false}addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(updateProgress)}},{passive:true});addEventListener('resize',updateProgress);updateProgress();
const sweetMessages=['Tu sonrisa hace más bonito mi mundo. ♡','Contigo, cualquier instante se vuelve especial. ♡','Quiero celebrar tus sueños y abrazarte en tus días difíciles. ♡','Qué suerte la mía de tenerte en mi vida, Valentina. ♡'];
const viewer=document.getElementById('photo-viewer'),photos=[...document.querySelectorAll('.photo')];let current=0;function showPhoto(index){current=(index+photos.length)%photos.length;const source=photos[current].querySelector('img');document.getElementById('viewer-image').src=source.src;document.getElementById('viewer-image').alt=source.alt;const caption=document.getElementById('viewer-caption');caption.textContent=sweetMessages[current];if(!reduced.matches)caption.animate([{opacity:0,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:450,easing:'ease-out'})}photos.forEach((photo,i)=>photo.addEventListener('click',()=>{showPhoto(i);viewer.showModal()}));viewer.querySelector('.viewer-close').addEventListener('click',()=>viewer.close());viewer.querySelector('.viewer-prev').addEventListener('click',()=>showPhoto(current-1));viewer.querySelector('.viewer-next').addEventListener('click',()=>showPhoto(current+1));viewer.addEventListener('click',event=>{if(event.target===viewer){const r=viewer.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)viewer.close()}});viewer.addEventListener('keydown',event=>{if(event.key==='ArrowRight'){event.preventDefault();showPhoto(current+1)}if(event.key==='ArrowLeft'){event.preventDefault();showPhoto(current-1)}});
